// Picks the layout data (ground raster, meshes, kerb / sea lines, lots, roads) of the active open-style map. openmap.js and
// citylite.js import from here instead of from one fixed layout file, so a new map only needs a new data module with the
// same exports (Open City: openlayout.js; Harbor District: harborlayout.js, generated by tools/gen-harbor-layout.mjs).
import * as open from './openlayout.js';
import * as harbor from './harborlayout.js';
import { MAP_ID } from './mapid.js';

const L = MAP_ID === 'harbor' ? harbor : open;
export const { CELL, NX, NZ, X0, Z0, SCALE, RLE, MESH, LINES, MARKS, BOUNDS, PARKS, PLAZA, BLOCKS, LOTS, AVENUES, STREETS, EXITS, SPAWN } = L;
export const LOT_INSET = L.LOT_INSET ?? [6, 4]; // [min, range] metres a building is pulled in from its lot edge (Open City: 6..10)
